private lemma prod_blk_ne_zero {U : Finset ℕ} (hU : ∀ x ∈ U, 1 ≤ x) :
    ∏ x ∈ U, blk x ≠ 0 :=
  Finset.prod_ne_zero_iff.mpr fun x hx => blk_ne_zero (hU x hx)

private lemma erdos_1193_set (N : ℕ) :
    {n : ℕ | n ∈ Set.Iio N ∧
      Nat.card {p : ↥(Set.univ : Set ℕ) × ↥(Set.univ : Set ℕ) // (p.1 : ℕ) + (p.2 : ℕ) = n}
        = n + 1} = Set.Iio N := by
  ext n
  simp [erdos_1193_card]

private lemma erdos_532_N_succ (a : ℕ → ℕ) (k : ℕ) :
    erdos_532_N a (k + 1) = erdos_532_N a k + 1 + ∑ j ∈ Finset.range (erdos_532_N a k), a j :=
  rfl

private lemma degree_pair (a b : ℕ) :
    (Finsupp.single (0 : Fin 2) a + Finsupp.single (1 : Fin 2) b).degree = a + b := by
  rw [map_add, Finsupp.degree_single, Finsupp.degree_single]

private lemma sumset_mono {p : ℕ} {A B : Finset (ZMod p)} (h : A ⊆ B) :
    sumset A ⊆ sumset B :=
  Finset.image_subset_image (Finset.filter_subset_filter _ (Finset.product_subset_product h h))
